package fraymus.workspace;
import org.json.*;
import java.util.*;

/** Fixed manual-phase windows, independently annotated original frames, immutable first evaluation. */
final class MatTrials041 {
    static final String VERSION="manual-physical-windows-041-v1";
    static List<String> phases(String kind){return switch(kind){case "stationary"->List.of("start");case "movement"->List.of("start","transition","end");case "occlusion"->List.of("start","hidden","revealed");default->throw new IllegalArgumentException("Choose stationary, movement or occlusion");};}
    static JSONArray window(JSONObject run,String phase){var a=new JSONArray();for(Object raw:run.getJSONArray("trace")){var row=(JSONObject)raw;if(row.getString("phase").equals(phase))a.put(row);}return a;}
    static int required(JSONObject run,String phase){return run.getString("kind").equals("stationary")?12:phase.equals("transition")?0:8;}
    static double[] mean(JSONArray rows,boolean all){double[] p={0,0};int n=0;for(Object raw:rows){var e=((JSONObject)raw).getJSONObject("estimate");if(!e.getBoolean("accepted")){if(all)throw new IllegalArgumentException("Fixed endpoint/start window includes an unmeasured sample");continue;}var a=e.getJSONArray("positionM");p[0]+=a.getDouble(0);p[1]+=a.getDouble(1);n++;}if(n==0)throw new IllegalArgumentException("No measured positions in fixed window");p[0]/=n;p[1]/=n;return p;}
    static JSONObject evaluate(JSONObject run,JSONObject references){
        SpatialScene.keys(references,"source","confirmed","frames");if(!references.getBoolean("confirmed")||references.getString("source").isBlank()||references.getString("source").length()>1500)throw new IllegalArgumentException("Confirm independent physical marks/visibility and declare raw-frame inspection source");
        if(!run.getString("status").equals("completed"))throw new IllegalArgumentException("Finish this recording before evaluating");var out=new JSONObject().put("version",VERSION).put("runId",run.getString("id")).put("codeSha256",run.getString("codeSha256")).put("registrationId",run.getString("registrationId")).put("references",references).put("passed",false);
        var fixed=new JSONArray();for(String phase:phases(run.getString("kind"))){if(phase.equals("transition"))continue;var rows=window(run,phase);if(rows.length()!=required(run,phase))return out.put("status","unscored").put("reason","Fixed phase "+phase+" requires exactly"+required(run,phase)+" source samples");for(Object raw:rows)fixed.put(raw);}
        var refs=references.getJSONArray("frames");if(refs.length()!=fixed.length())throw new IllegalArgumentException("Independently annotate every fixed-window original, with exact source hash");var byOrdinal=new HashMap<Integer,JSONObject>();for(Object raw:refs){var ref=(JSONObject)raw;SpatialScene.keys(ref,"ordinal","imageSha256","visible","atDeclaredMark");int n=ref.getInt("ordinal");if(n!=ref.getDouble("ordinal")||byOrdinal.put(n,ref)!=null)throw new IllegalArgumentException("Distinct integer source ordinals required");}
        int geometryFailures=0;for(Object raw:fixed){var row=(JSONObject)raw;var ref=byOrdinal.get(row.getInt("ordinal"));if(ref==null||!ref.getString("imageSha256").equals(row.getJSONObject("frame").getString("imageSha256")))throw new IllegalArgumentException("Ground-truth annotation does not match fixed original frame");boolean hidden=row.getString("phase").equals("hidden");if(ref.isNull("visible"))return out.put("status","unscored").put("reason","Visibility is unresolved in an independently inspected original");if(ref.getBoolean("visible")==hidden)return out.put("status","unscored").put("reason","Actual visibility contradicts declared manual phase");if(run.getString("kind").equals("movement")&&!ref.optBoolean("atDeclaredMark",false))return out.put("status","unscored").put("reason","Independent endpoint mark alignment is not confirmed");if(!row.getJSONObject("reference").getBoolean("valid"))geometryFailures++;}
        var metrics=new JSONObject().put("fixedSamples",fixed.length()).put("referenceFailures",geometryFailures);boolean passed=false;try{
            var first=window(run,"start");var a=mean(first,true);if(run.getString("kind").equals("stationary")){double square=0;for(Object raw:first){var p=PlaneCalibration.point(((JSONObject)raw).getJSONObject("estimate").getJSONArray("positionM"));square+=Math.pow(p[0]-a[0],2)+Math.pow(p[1]-a[1],2);}double rms=Math.sqrt(square/first.length());metrics.put("jitterRmsM",rms).put("toleranceM",.003);passed=rms<=.003;}
            else if(run.getString("kind").equals("movement")){var last=mean(window(run,"end"),true);var tape=run.getJSONObject("registration").getJSONObject("fit").getJSONObject("tape");var plane=new PlaneCalibration(run.getJSONObject("registration").getJSONObject("geometry"));var pa=PlaneCalibration.point(tape.getJSONArray("a"));var pb=PlaneCalibration.point(tape.getJSONArray("b"));pa=plane.project(pa[0],pa[1]);pb=plane.project(pb[0],pb[1]);double sign=(run.getDouble("toMark")-run.getDouble("fromMark"))/(tape.getDouble("markB")-tape.getDouble("markA")),length=Math.abs(run.getDouble("toMark")-run.getDouble("fromMark"))*MatRegistration041.unit(tape.getString("unit")),dx=(pb[0]-pa[0])*sign,dy=(pb[1]-pa[1])*sign,n=Math.hypot(dx,dy);double[] expected={dx*length/n,dy*length/n},actual={last[0]-a[0],last[1]-a[1]};double error=PlaneCalibration.distance(actual,expected);metrics.put("firstMeanM",new JSONArray(a)).put("lastMeanM",new JSONArray(last)).put("expectedDeltaM",new JSONArray(expected)).put("actualDeltaM",new JSONArray(actual)).put("vectorErrorM",error).put("toleranceM",.010);passed=error<=.010;}
            else {int falseMeasurements=0,recovered=0;for(Object raw:window(run,"hidden"))if(((JSONObject)raw).getJSONObject("estimate").getBoolean("accepted"))falseMeasurements++;var reveal=window(run,"revealed");for(Object raw:reveal)if(((JSONObject)raw).getJSONObject("estimate").getBoolean("accepted"))recovered++;var b=mean(reveal,false);double error=PlaneCalibration.distance(a,b);metrics.put("hiddenAcceptedMeasurements",falseMeasurements).put("recovered",recovered).put("revealed",reveal.length()).put("recoveryCoverage",recovered/(double)reveal.length()).put("returnErrorM",error).put("toleranceM",.010);passed=falseMeasurements==0&&recovered/(double)reveal.length()>=.8&&error<=.010;}
        }catch(IllegalArgumentException e){metrics.put("failure",e.getMessage());}
        return out.put("status","evaluated").put("metrics",metrics).put("passed",passed&&geometryFailures==0).put("qualification","User-declared physical marks and independent inspection of original fixed-window frames. Source phase boundaries are manual; no timed cue, prediction-derived truth, calibrated probability or native actuation.");
    }
}
